args.command:
/bin/bash -lc "node --input-type=module <<'EOF'
const origin = 'http://localhost:3100/'
const first = await (await fetch(origin)).text()
await new Promise(resolve => setTimeout(resolve, 30))
const second = await (await fetch(origin)).text()
const metadata = html => html.match(/Request ([0-9a-f-]{36}) generated at (["'^ <]+) '"\\(sample ([0-9.]+)\\)/)?.slice(1)
const firstMetadata = metadata(first)
const secondMetadata = metadata(second)
const shell = first.includes('<nav>Operations</nav>') && first.includes('<h1>Deployment health</h1>') && first.includes('Loading request details')
console.log(JSON.stringify({shell, firstMetadata, secondMetadata, freshPerRequest: Boolean(firstMetadata && secondMetadata && firstMetadata.every((value, index) => value "'!== secondMetadata[index]))}, null, 2))
if (!shell || !firstMetadata || !secondMetadata || firstMetadata.some((value, index) => value === secondMetadata[index])) process.exitCode = 1
EOF'

